mapper.select:
SELECT p.*, c.name AS category_name, u.nickname AS publisher_name FROM pet p LEFT JOIN pet_category c ON p.category_id = c.id LEFT JOIN sys_user u ON p.publisher_id = u.id
AND p.category_id = #{categoryId}
AND p.status = #{status}
AND (p.name LIKE CONCAT('%', #{keyword}, '%') OR p.breed LIKE CONCAT('%', #{keyword}, '%') OR p.description LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY p.create_time DESC
